    options: [
      { "id": "a", "text": "SYN set, ACK not set" },
      { "id": "b", "text": "FIN set, ACK set" },
      { "id": "c", "text": "RST set, PSH set" },
      { "id": "d", "text": "ACK set, SYN not set" }
    ],
